-- PrajaPulse Citizen Dashboard Dataset — exactly 1,000 synthetic rows
-- MySQL 8.0+ | Synthetic demo data only; no real citizens or verified claims.
-- IMPORTANT MERGE CONTRACT:
-- 1) Run prajapulse_ngo_dataset_1000.sql FIRST, then this file.
-- 2) civic_issues.issue_id is the shared canonical issue key used by both Citizen and NGO modules.
-- 3) This file deliberately does NOT create a second issue table or duplicate issue records.
-- 4) NGO-side tables can link to the same issue IDs through civic_issues, ngo_issue_associations,
--    campaign_issue_links, and field operations. Align names with your actual application schema before production.
-- 5) Demo-only emails, evidence paths, predictions, and impact estimates must not be treated as verified.
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

CREATE TABLE IF NOT EXISTS citizen_profiles (
  citizen_id VARCHAR(16) PRIMARY KEY,
  display_name VARCHAR(120) NOT NULL,
  demo_email VARCHAR(180) NOT NULL UNIQUE,
  home_city VARCHAR(80) NOT NULL,
  home_state VARCHAR(80) NOT NULL,
  preferred_language VARCHAR(20) NOT NULL DEFAULT 'en',
  points INT NOT NULL DEFAULT 0,
  reputation_level ENUM('newcomer','contributor','community_builder','civic_champion') NOT NULL DEFAULT 'newcomer',
  profile_visibility ENUM('public','community','private') NOT NULL DEFAULT 'community',
  created_at DATE NOT NULL,
  data_source VARCHAR(30) NOT NULL DEFAULT 'synthetic_demo',
  INDEX idx_citizen_location (home_state,home_city)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS issue_interactions (
  interaction_id VARCHAR(16) PRIMARY KEY,
  citizen_id VARCHAR(16) NOT NULL,
  issue_id VARCHAR(16) NOT NULL,
  interaction_type ENUM('view','comment','share','save','follow','search_open') NOT NULL,
  interaction_text TEXT,
  created_at DATETIME NOT NULL,
  data_source VARCHAR(30) NOT NULL DEFAULT 'synthetic_demo',
  FOREIGN KEY (citizen_id) REFERENCES citizen_profiles(citizen_id),
  FOREIGN KEY (issue_id) REFERENCES civic_issues(issue_id),
  INDEX idx_interaction_issue (issue_id,interaction_type)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS issue_votes (
  vote_id VARCHAR(16) PRIMARY KEY,
  citizen_id VARCHAR(16) NOT NULL,
  issue_id VARCHAR(16) NOT NULL,
  vote_value TINYINT NOT NULL,
  vote_reason VARCHAR(240),
  created_at DATETIME NOT NULL,
  data_source VARCHAR(30) NOT NULL DEFAULT 'synthetic_demo',
  UNIQUE KEY uq_citizen_issue_vote (citizen_id,issue_id),
  CHECK (vote_value IN (-1,1)),
  FOREIGN KEY (citizen_id) REFERENCES citizen_profiles(citizen_id),
  FOREIGN KEY (issue_id) REFERENCES civic_issues(issue_id),
  INDEX idx_votes_issue (issue_id,vote_value)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS issue_evidence (
  evidence_id VARCHAR(16) PRIMARY KEY,
  issue_id VARCHAR(16) NOT NULL,
  uploaded_by_citizen_id VARCHAR(16) NOT NULL,
  evidence_type ENUM('photo','video','document','location_check') NOT NULL,
  file_path VARCHAR(255) NOT NULL,
  caption TEXT,
  validation_status ENUM('pending','accepted','rejected','needs_review') NOT NULL,
  uploaded_at DATETIME NOT NULL,
  data_source VARCHAR(30) NOT NULL DEFAULT 'synthetic_demo',
  FOREIGN KEY (issue_id) REFERENCES civic_issues(issue_id),
  FOREIGN KEY (uploaded_by_citizen_id) REFERENCES citizen_profiles(citizen_id),
  INDEX idx_evidence_issue (issue_id,validation_status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS ai_predictions (
  prediction_id VARCHAR(16) PRIMARY KEY,
  issue_id VARCHAR(16) NOT NULL,
  model_name VARCHAR(80) NOT NULL,
  predicted_priority ENUM('low','medium','high','critical') NOT NULL,
  confidence DECIMAL(5,4) NOT NULL,
  duplicate_cluster_id VARCHAR(24),
  duplicate_probability DECIMAL(5,4) NOT NULL,
  predicted_category VARCHAR(50) NOT NULL,
  prediction_status ENUM('suggested','reviewed','accepted','overridden') NOT NULL,
  generated_at DATETIME NOT NULL,
  model_version VARCHAR(40) NOT NULL,
  data_source VARCHAR(30) NOT NULL DEFAULT 'synthetic_demo',
  CHECK (confidence >= 0 AND confidence <= 1),
  CHECK (duplicate_probability >= 0 AND duplicate_probability <= 1),
  FOREIGN KEY (issue_id) REFERENCES civic_issues(issue_id),
  INDEX idx_prediction_issue (issue_id,generated_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS suggested_actions (
  action_id VARCHAR(16) PRIMARY KEY,
  issue_id VARCHAR(16) NOT NULL,
  action_path ENUM('citizen_community','government_authority') NOT NULL,
  action_title VARCHAR(180) NOT NULL,
  action_description TEXT NOT NULL,
  suggested_by ENUM('ai','citizen','ngo','government') NOT NULL,
  action_status ENUM('suggested','accepted','in_progress','completed','dismissed') NOT NULL,
  created_at DATETIME NOT NULL,
  data_source VARCHAR(30) NOT NULL DEFAULT 'synthetic_demo',
  FOREIGN KEY (issue_id) REFERENCES civic_issues(issue_id),
  INDEX idx_suggested_actions (issue_id,action_path,action_status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS root_cause_analysis (
  root_cause_id VARCHAR(16) PRIMARY KEY,
  issue_id VARCHAR(16) NOT NULL,
  cause_category VARCHAR(80) NOT NULL,
  cause_summary TEXT NOT NULL,
  supporting_signal VARCHAR(180),
  confidence DECIMAL(5,4) NOT NULL,
  review_status ENUM('unreviewed','community_reviewed','expert_verified','rejected') NOT NULL,
  mapping_layer_ref VARCHAR(40),
  created_at DATETIME NOT NULL,
  data_source VARCHAR(30) NOT NULL DEFAULT 'synthetic_demo',
  FOREIGN KEY (issue_id) REFERENCES civic_issues(issue_id),
  INDEX idx_root_cause_issue (issue_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS impact_forecasts (
  forecast_id VARCHAR(16) PRIMARY KEY,
  issue_id VARCHAR(16) NOT NULL,
  proposed_action VARCHAR(180) NOT NULL,
  estimated_people_benefited INT NOT NULL,
  estimated_cost_inr DECIMAL(12,2),
  expected_days_to_impact INT,
  forecast_confidence DECIMAL(5,4) NOT NULL,
  assumptions TEXT,
  forecast_status ENUM('draft','shown_to_citizen','reviewed','compared_with_outcome') NOT NULL,
  generated_at DATETIME NOT NULL,
  data_source VARCHAR(30) NOT NULL DEFAULT 'synthetic_demo',
  FOREIGN KEY (issue_id) REFERENCES civic_issues(issue_id),
  INDEX idx_forecast_issue (issue_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS citizen_notifications (
  notification_id VARCHAR(16) PRIMARY KEY,
  citizen_id VARCHAR(16) NOT NULL,
  issue_id VARCHAR(16),
  notification_type ENUM('issue_update','nearby_issue','daily_briefing','ngo_activity','vacancy','positive_story','community_milestone','awareness') NOT NULL,
  title VARCHAR(180) NOT NULL,
  message TEXT NOT NULL,
  is_read TINYINT(1) NOT NULL DEFAULT 0,
  scheduled_for DATETIME NOT NULL,
  data_source VARCHAR(30) NOT NULL DEFAULT 'synthetic_demo',
  FOREIGN KEY (citizen_id) REFERENCES citizen_profiles(citizen_id),
  FOREIGN KEY (issue_id) REFERENCES civic_issues(issue_id),
  INDEX idx_notifications_inbox (citizen_id,is_read,scheduled_for)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS positive_stories (
  story_id VARCHAR(16) PRIMARY KEY,
  issue_id VARCHAR(16) NOT NULL,
  headline VARCHAR(220) NOT NULL,
  story_text TEXT NOT NULL,
  media_path VARCHAR(255),
  publication_status ENUM('draft','needs_consent','approved','published','withdrawn') NOT NULL,
  impact_summary VARCHAR(240),
  published_at DATETIME,
  data_source VARCHAR(30) NOT NULL DEFAULT 'synthetic_demo',
  FOREIGN KEY (issue_id) REFERENCES civic_issues(issue_id),
  INDEX idx_positive_story (publication_status,published_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS awareness_content (
  content_id VARCHAR(16) PRIMARY KEY,
  topic_category VARCHAR(60) NOT NULL,
  language_code VARCHAR(20) NOT NULL,
  title VARCHAR(180) NOT NULL,
  body TEXT NOT NULL,
  format_type ENUM('short_video','carousel','article','quiz','infographic') NOT NULL,
  related_issue_id VARCHAR(16),
  published_status ENUM('draft','published','archived') NOT NULL,
  created_at DATE NOT NULL,
  data_source VARCHAR(30) NOT NULL DEFAULT 'synthetic_demo',
  FOREIGN KEY (related_issue_id) REFERENCES civic_issues(issue_id),
  INDEX idx_awareness_topic_language (topic_category,language_code,published_status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS cleanup_events (
  event_id VARCHAR(16) PRIMARY KEY,
  issue_id VARCHAR(16) NOT NULL,
  organizer_citizen_id VARCHAR(16) NOT NULL,
  related_organization_id VARCHAR(16),
  event_title VARCHAR(180) NOT NULL,
  event_description TEXT,
  city VARCHAR(80) NOT NULL,
  state VARCHAR(80) NOT NULL,
  locality VARCHAR(80),
  starts_at DATETIME NOT NULL,
  capacity INT NOT NULL,
  event_status ENUM('proposed','open','full','completed','cancelled') NOT NULL,
  safety_review_status ENUM('not_required','pending','approved','rejected') NOT NULL,
  data_source VARCHAR(30) NOT NULL DEFAULT 'synthetic_demo',
  FOREIGN KEY (issue_id) REFERENCES civic_issues(issue_id),
  FOREIGN KEY (organizer_citizen_id) REFERENCES citizen_profiles(citizen_id),
  FOREIGN KEY (related_organization_id) REFERENCES organizations(organization_id),
  INDEX idx_cleanup_event (event_status,starts_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS cleanup_event_registrations (
  registration_id VARCHAR(16) PRIMARY KEY,
  event_id VARCHAR(16) NOT NULL,
  citizen_id VARCHAR(16) NOT NULL,
  registration_status ENUM('registered','waitlisted','cancelled','attended','no_show') NOT NULL,
  registered_at DATETIME NOT NULL,
  contribution_points INT NOT NULL DEFAULT 0,
  data_source VARCHAR(30) NOT NULL DEFAULT 'synthetic_demo',
  UNIQUE KEY uq_event_citizen (event_id,citizen_id),
  FOREIGN KEY (event_id) REFERENCES cleanup_events(event_id),
  FOREIGN KEY (citizen_id) REFERENCES citizen_profiles(citizen_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS ngo_vacancy_applications (
  application_id VARCHAR(16) PRIMARY KEY,
  organization_id VARCHAR(16) NOT NULL,
  vacancy_title VARCHAR(180) NOT NULL,
  vacancy_type ENUM('volunteer','internship','part_time','full_time') NOT NULL,
  city VARCHAR(80) NOT NULL,
  state VARCHAR(80) NOT NULL,
  description TEXT,
  application_form_url VARCHAR(255),
  application_deadline DATE,
  vacancy_status ENUM('open','paused','closed','filled') NOT NULL,
  created_at DATE NOT NULL,
  data_source VARCHAR(30) NOT NULL DEFAULT 'synthetic_demo',
  FOREIGN KEY (organization_id) REFERENCES organizations(organization_id),
  INDEX idx_vacancy_location (state,city,vacancy_status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS citizen_report_snapshots (
  report_id VARCHAR(16) PRIMARY KEY,
  citizen_id VARCHAR(16) NOT NULL,
  report_period ENUM('weekly','monthly','annual') NOT NULL,
  period_start DATE NOT NULL,
  period_end DATE NOT NULL,
  issues_reported INT NOT NULL,
  votes_cast INT NOT NULL,
  community_actions_completed INT NOT NULL,
  issues_resolved INT NOT NULL,
  generated_at DATETIME NOT NULL,
  data_source VARCHAR(30) NOT NULL DEFAULT 'synthetic_demo',
  FOREIGN KEY (citizen_id) REFERENCES citizen_profiles(citizen_id),
  INDEX idx_citizen_report_period (citizen_id,report_period,period_start)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS community_leaderboard_snapshots (
  leaderboard_id VARCHAR(16) PRIMARY KEY,
  citizen_id VARCHAR(16) NOT NULL,
  scope_type ENUM('ward','city','state','platform') NOT NULL,
  scope_name VARCHAR(100) NOT NULL,
  period_type ENUM('weekly','monthly','annual') NOT NULL,
  period_start DATE NOT NULL,
  points INT NOT NULL,
  rank_position INT NOT NULL,
  generated_at DATETIME NOT NULL,
  data_source VARCHAR(30) NOT NULL DEFAULT 'synthetic_demo',
  FOREIGN KEY (citizen_id) REFERENCES citizen_profiles(citizen_id),
  INDEX idx_leaderboard_scope (scope_type,scope_name,period_type,rank_position)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS chatbot_sessions (
  session_id VARCHAR(16) PRIMARY KEY,
  citizen_id VARCHAR(16) NOT NULL,
  language_code VARCHAR(20) NOT NULL,
  topic_category VARCHAR(60),
  started_at DATETIME NOT NULL,
  session_status ENUM('open','completed','abandoned') NOT NULL,
  data_source VARCHAR(30) NOT NULL DEFAULT 'synthetic_demo',
  FOREIGN KEY (citizen_id) REFERENCES citizen_profiles(citizen_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS chatbot_messages (
  message_id VARCHAR(16) PRIMARY KEY,
  session_id VARCHAR(16) NOT NULL,
  sender_type ENUM('citizen','assistant') NOT NULL,
  message_text TEXT NOT NULL,
  related_issue_id VARCHAR(16),
  sent_at DATETIME NOT NULL,
  data_source VARCHAR(30) NOT NULL DEFAULT 'synthetic_demo',
  FOREIGN KEY (session_id) REFERENCES chatbot_sessions(session_id),
  FOREIGN KEY (related_issue_id) REFERENCES civic_issues(issue_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;



















